def shortest_path(graph, source, target):
    # Initialize distances and paths
    distances = {node: float("inf") for node in graph}
    paths = {node: [] for node in graph}

    # Priority queue to store (distance, node) pairs, using the max weight as the priority
    from heapq import heappush, heappop
    priority_queue = [(0, source)]  # (distance, node)

    # If the target is the source, the source itself is the path
    if source == target:
        return (0, [source])

    # Run Dijkstra's algorithm
    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        # If we've reached the target node, we can return the path
        if current_node == target:
            return (current_distance, paths[current_node])

        # If we've already found a shorter path to this node, skip it
        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # If the path through the current node is shorter, update the distances and paths
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                paths[neighbor] = paths[current_node] + [neighbor]
                # Push the neighbor to the priority queue
                heappush(priority_queue, (distance, neighbor))

    # If we exit the loop without finding a path, the target is unreachable
    return (float("inf"), None)
