    # Initialize the parent array for reconstructing the path.
    parent = {node: None for node in graph}
    # Priority queue with priority as distance from source, and arbitrary sort for initial entries.
    from heapq import heappush, heappop
    queue = [(0, source)]
    distance[source] = 0

    while queue:
        current_distance, current_node = heappop(queue)
        # If we have reached the target, reconstruct the path.
        if current_node == target:
            path = []
            while current_node:
                path.append(current_node)
                current_node = parent[current_node]
            return (current_distance, path[::-1])
        # Explore neighbors.
