Here's the complete code:

```python
def shortest_path(graph, source, target):
    # Number of nodes
    n = len(graph)

    # Initialize the distance matrix
    distance = [[float("inf")] * n for _ in range(n)]

    # Initialize the path matrix (All nodes are unreachable from each other initially)
    path = [["None"] * n for _ in range(n)]

    # Distance matrix: initially the distance from a node to itself is 0, and the distance from any other node is infinity
    for i in range(n):
        distance[i][i] = 0
        for neighbor, weight in graph[i]:
            distance[i][neighbor] = weight

    # All pairs shortest path (Floyd-Warshall algorithm)
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if distance[i][k] + distance[k][j] < distance[i][j]:
                    distance[i][j] = distance[i][k] + distance[k][j]
                    path[i][j] = path[k][j] + [j]

    # Return the shortest path if it exists, otherwise return infinity and None
    if distance[source][target] == float("inf"):
        return (float("inf"), None)
    else:
        return (distance[source][target], path[source][target])

