def shortest_path(graph, source, target):
    # Initialize the maximum distance to a high number (representing infinity) for all nodes.
    max_distance := 2000000000 # 2000000000 is an approximation of infinity for most practical purposes.

    # Dictionary to store the minimum distance to reach each node and its path.
    distance = {node: max_distance for node in graph}
    path = {node: None for node in graph}

    # Priority queue to store nodes to be explored, ordered by their current minimum distance.
    priority_queue = [(0, source)]

    # Process the queue until it's empty.
    while priority_queue:
        current_distance, current_node = heappop(priority_queue)

        # If we've reached the target node, we can reconstruct the path.
        if current_node == target:
            path_reconstructed = []
            while current_node is not None:
                path_reconstructed.append(current_node)
                current_node = path[current_node]
            return (current_distance, path_reconstructed[::-1])

        # If the current node is not in the graph, skip it.
        if current_node not in graph:
            continue

        # Explore the neighbors of the current node.
        for neighbor, weight in graph[current_node]:
            distance_to_neighbor = current_distance + weight

            # If there's a better path to the neighbor (a shorter path), update the distance and the path.
            if distance_to_neighbor < distance[neighbor]:
                distance[neighbor] = distance_to_neighbor
                path[neighbor] = current_node
