    # Initialize the distance and path dictionaries
    distances = {node: float("inf") for node in graph}
    path = {node: [] for node in graph}

    # Priority queue for BFS (we use a simple list for simplicity)
    queue = [(source, [source])]
    distances[source] = 0

    # Function to perform BFS
    def bfs():
        while queue:
            current_node, path_to_current = queue.pop(0)
            for neighbor, weight in graph[current_node]:
                if distances[neighbor] > distances[current_node] + weight:
                    distances[neighbor] = distances[current_node] + weight
                    path[neighbor] = path_to_current + [neighbor]
                    queue.append((neighbor, path_to_current + [neighbor]))
                if neighbor == target:
                    return path[neighbor]
        return None

    return distances[target], bfs()

