def shortest_path(graph, source, target):
    def bfs_shortest_path(source, target):
        visited = [False] * len(graph)
        queue = []
        path = []
        path[0] = source
        visited[source] = True
        queue.append(source)

        while queue:
            u = queue.pop(0)
            for neighbour, weight in graph[u]:
                if not visited[neighbour]:
                    path.append(neighbour)
                    visited[neighbour] = True
                    queue.append(neighbour)
                    if neighbour == target:
                        return path, weight
        return None, float("inf")

    def dfs_shortest_path(source, target, visited, parent, distance, path):
        visited[source] = True
        path.append(source)

        if source == target:
            return path, distance
        min_distance, min_path = float("inf"), None
        for neighbour, weight in graph[source]:
            if not visited[neighbour]:
                new_distance = distance + weight
                new_path, new_distance = dfs_shortest_path(neighbour, target, visited, parent, new_distance, path)
                if new_distance < min_distance:
                    min_distance, min_path = new_distance, new_path
        path.pop()
        return min_path, min_distance

    visited = [False] * len(graph)
    path = []
    parent = [-1] * len(graph)

    # Try BFS first
    path, distance = bfs_shortest_path(source, target)
    if path:
        return (distance, path)

    # If BFS didn't work, we try DFS
    path, distance = dfs_shortest_path(source, target, visited, parent, 0, path)
    return (distance, path) if path else (float("inf"), None)

