from collections import defaultdict, deque
import math

def shortest_path(graph, source, target):
    def bfs(graph, source, target):
        # Initialize priority queue with source node and distance 0
        queue = deque([(source, 0)])
        # Map to keep track of the shortest distance to each node found
        distances = {source: 0}
        # Map to keep track of the previous node on the shortest path
        previous = {source: None}

        while queue:
            current_node, current_distance = queue.popleft()
            # If the current node is the target, return the path
            if current_node == target:
                path = []
                while current_node is not None:
                    path.append(current_node)
                    current_node = previous[current_node]
                path.reverse()
                return (current_distance, path)

            # Explore all neighbors of the current node
            for neighbor, weight in graph.get(current_node, []):
                if neighbor not in distances or distances[neighbor] > current_distance + weight:
                    distances[neighbor] = current_distance + weight
                    previous[neighbor] = current_node
                    queue.append((neighbor, current_distance + weight))

        # If the target is not reachable, return infinity
        return (math.inf, None)

    return bfs(graph, source, target)

