from collections import defaultdict, deque

def shortest_path(graph, source, target):
    # A set to keep track of visited nodes
    visited = set()

    # A dictionary to store the shortest distance from the source to each node
    distances = {node: float('inf') for node in graph}
    distances[source] = 0

    # A dictionary to store the shortest path from the source to each node
    paths = {node: [] for node in graph}
    paths[source] = [source]

    # A queue for BFS
    queue = deque([source])

    while queue:
        current_node = queue.popleft()

        for neighbor, weight in graph[current_node]:
            if neighbor in visited:
                continue

            new_distance = distances[current_node] + weight
            if new_distance < distances[neighbor]:
                distances[neighbor] = new_distance
                paths[neighbor] = paths[current_node] + [neighbor]
                if neighbor == target:
                    return (distances[neighbor], paths[neighbor])
                queue.append(neighbor)

            visited.add(neighbor)

    # If we reach here, it means the target is unreachable
    return (float('inf'), None)

