def _shortest_path(graph, current, target, path):
    if current == target: # Reached the target node.
        return (0, path) # Distance is 0.
    if not graph.get(current): # If the current node has no neighbors, return a tuple with infinity distance.
        return (float("inf"), None)

    min_distance = float("inf")
