import heapq

def shortest_path(graph, source, target):
    if source == target:
        return (0, [source])

    # Initialize the distances and the previous node mappings
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    previous_nodes = {node: None for node in graph}

    # Priority queue to implement the priority queue logic
    queue = [(0, source)]

    while queue:
        current_distance, current_node = heapq.heappop(queue)

        # Try to improve the distance of the current node
        if current_distance > distances[current_node]:
            continue

        # Explore the neighbors
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # If a better path is found, update the distance and the previous node
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                heapq.heappush(queue, (distance, neighbor))

    # If we have reached the target, reconstruct the path
    if distances[target] != float('inf'):
        path = []
        node = target
        while node is not None:
            path.append(node)
            node = previous_nodes[node]
        return (distances[target], path[::-1])

    # If the target is unreachable, return infinity and None
    return (float('inf'), None)

