def shortest_path(graph, source, target, max_steps=50, max_distance=50):
    # Return a constant message if the target is unreachable.
    if target not in graph:
        return float("inf"), None

    # Initialize variables
    distances = {node: float("inf") for node in graph}
    previous_nodes = {node: None for node in graph}
    distances[source] = 0
    queue = [[source, 0]]  # Each element is a pair [node, distance]

