        if current_node == target:
            break
        if current_distance > distances[current_node]:
            continue
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                queue.append([neighbor, distance])
                # If we reach the target, we break the loop since we want the shortest path.
                if neighbor == target:
                    break
        # If the maximum number of steps is reached, return infinity and None.
        if len(queue) > max_steps:
            return float("inf"), None

    # If we reach here, it means the target is unreachable.
    if previous_nodes[target] is None:
        return float("inf"), None
    # Reconstruct the path from previous_nodes and return the distance.
    path = []
    while target is not None:
        path.append(target)
        target = previous_nodes[target]
    path.reverse()
    return distances[target], path
